UPDATE public.vault_articles SET lesson_number = 1, display_order = 301, course_role = 'foundations', read_time_min = 4, quiz = $v$[{"q": "What does a speculative chip mean in this course?", "choices": ["The practice may be valuable but the explanation offered for it is not supported", "The teacher is being dishonest", "The practice is worthless"], "correct": 0, "explain": "Speculative rates the story, not the exercise. Keep the practice, drop the explanation."}, {"q": "Which three sentences should you finish for every source?", "choices": ["The plot, the author, the year", "The one idea, the practice, the claim you are not buying", "The price, the length, the rating"], "correct": 1, "explain": "That is the reading method: it keeps the useful part and names what you are leaving on the shelf."}]$v$::jsonb, updated_at = now() WHERE slug = 'how-to-read-a-teacher';
UPDATE public.vault_articles SET lesson_number = 2, display_order = 302, course_role = 'protocol', read_time_min = 4, quiz = $v$[{"q": "In Clear's model, where does lasting change happen?", "choices": ["In the outcome you set", "In the system and the identity underneath it", "In the app you track it with"], "correct": 1, "explain": "Outcomes are where results show up; systems and identity are where they are produced."}, {"q": "What did Lally's study find about missing a single day?", "choices": ["It doubles the time needed", "It resets the habit to zero", "It made no measurable difference to the automaticity curve"], "correct": 2, "explain": "One miss does not undo the habit. Clear's rule follows: never miss twice."}, {"q": "Which is the two-minute rule?", "choices": ["Shrink the habit until starting takes two minutes; the entrance, not the goal", "Rest two minutes between habits", "Do every habit for exactly two minutes"], "correct": 0, "explain": "The tiny version gets you through the door. The full version can follow once showing up is automatic."}]$v$::jsonb, updated_at = now() WHERE slug = 'atomic-habits-identity';
UPDATE public.vault_articles SET lesson_number = 3, display_order = 303, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "What is the core practice of The Power of Now?", "choices": ["Planning the future in more detail", "Replacing negative thoughts with positive ones", "Noticing the thinker, so you observe a thought rather than being inside it"], "correct": 2, "explain": "Tolle does not ask you to win the argument with the mind. He asks you to watch it."}, {"q": "What did Killingsworth and Gilbert find?", "choices": ["A wandering mind predicts lower mood in the next moment", "Daydreaming improves mood", "Minds rarely wander"], "correct": 0, "explain": "Their experience-sampling study is the strongest single piece of evidence for training present-moment attention."}]$v$::jsonb, updated_at = now() WHERE slug = 'power-of-now-presence';
UPDATE public.vault_articles SET lesson_number = 4, display_order = 304, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "How does A New Earth define the ego?", "choices": ["The mind identifying with things that are not you", "Confidence in your abilities", "Arrogance and pride"], "correct": 0, "explain": "Ego here is identification. Anything you fold into the self becomes something you can lose."}, {"q": "Which research overlaps most with Tolle's dis-identification practice?", "choices": ["Strength periodisation", "Self-distancing and self-affirmation", "Sleep research"], "correct": 1, "explain": "Kross's self-distancing work shows that stepping back from the self reduces rumination and improves regulation."}]$v$::jsonb, updated_at = now() WHERE slug = 'new-earth-ego';
UPDATE public.vault_articles SET lesson_number = 5, display_order = 305, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "How does The Greatest Secret differ from The Secret?", "choices": ["It is a sequel about attracting more money", "It drops the law of attraction and turns to awareness itself", "It is the same book with new examples"], "correct": 1, "explain": "The first book was about attracting outcomes; the second is about noticing what notices."}, {"q": "What does suppression research show about pushing a feeling down?", "choices": ["It has no effect", "It works permanently", "The feeling rebounds stronger"], "correct": 2, "explain": "Wegner's ironic-process work: the suppressed content returns. Allowing it is the alternative the practice trains."}]$v$::jsonb, updated_at = now() WHERE slug = 'greatest-secret-awareness';
UPDATE public.vault_articles SET lesson_number = 6, display_order = 306, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "What is the lowest-score rule?", "choices": ["Average the eight scores and track the mean", "Ignore the weakest form and build on strengths", "The weakest form sets the ceiling on how rich the life feels, so it gets the next month of effort"], "correct": 2, "explain": "Money at five with family at one does not feel wealthy. Rebalancing starts at the bottom."}, {"q": "Which of the eight forms has the strongest longevity evidence behind it?", "choices": ["Community and family (close relationships)", "Craft", "Adventure"], "correct": 0, "explain": "The Harvard study and the loneliness meta-analyses put close relationships ahead of wealth for health and happiness."}]$v$::jsonb, updated_at = now() WHERE slug = 'eight-forms-of-wealth';
UPDATE public.vault_articles SET lesson_number = 7, display_order = 307, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "What is the shadow, in Jung's map?", "choices": ["Every quality you decided you are not, positive or negative, which then leaks", "Your worst memories", "Your evil side"], "correct": 0, "explain": "Ambition and tenderness end up in the shadow as often as anger. What is refused does not vanish."}, {"q": "What is the projection test?", "choices": ["Guessing what others think of you", "Noticing who irritates you out of proportion and asking where that quality lives in you", "Projecting confidence in meetings"], "correct": 1, "explain": "A disproportionate reaction to someone's manner is the most reliable pointer to your own shadow."}]$v$::jsonb, updated_at = now() WHERE slug = 'jung-shadow-individuation';
UPDATE public.vault_articles SET lesson_number = 8, display_order = 308, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "Which part of Dispenza's method has evidence behind it?", "choices": ["Curing illness through meditation", "Mental rehearsal of a specific state with feeling", "Quantum field explanations"], "correct": 1, "explain": "Motor imagery and emotion-regulation research support the rehearsal. The physics and the healing claims are not supported."}, {"q": "What should you rehearse?", "choices": ["Nothing specific; a general feeling of success", "The trophy at the end of the decade", "One specific scene from the next week, including the moment it gets hard"], "correct": 2, "explain": "Rehearsal works on process and obstacles, and it needs a real event within the week to land in."}]$v$::jsonb, updated_at = now() WHERE slug = 'dispenza-rehearsal';
UPDATE public.vault_articles SET lesson_number = 9, display_order = 309, course_role = 'protocol', read_time_min = 4, quiz = $v$[{"q": "Why is morning light first in the stack?", "choices": ["It replaces coffee", "It burns calories", "It sets the circadian clock that the rest of the day, including sleep, runs on"], "correct": 2, "explain": "Light is the dominant time-setter for the human clock; melatonin release is timed from the morning signal."}, {"q": "When should cold exposure NOT be done?", "choices": ["In the hours after strength training", "On rest days", "Before breakfast"], "correct": 0, "explain": "Post-training cold blunts the anabolic signalling the session was for. Put it before, or on a rest day."}, {"q": "What did the 2023 Balban trial find?", "choices": ["Meditation beat breathing", "Cyclic sighing beat mindfulness meditation for mood and arousal over a month", "Breathing has no effect on mood"], "correct": 1, "explain": "Five minutes a day of cyclic sighing outperformed meditation on mood and breathing rate."}]$v$::jsonb, updated_at = now() WHERE slug = 'huberman-protocol-stack';
UPDATE public.vault_articles SET lesson_number = 10, display_order = 310, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "What is the backwards law?", "choices": ["Reaching for a state signals its absence and keeps it absent; grabbing at security creates insecurity", "Bad things happen to good people", "Doing things in reverse order"], "correct": 0, "explain": "Thrash and you sink, relax and you float. Acceptance research found the same thing later."}, {"q": "What does Watts mean by life as music rather than a journey?", "choices": ["Nothing matters", "The point is the playing, not arriving at the final chord", "You should listen to more music"], "correct": 1, "explain": "A destination-only life turns every present moment into a corridor. The playing is the point."}]$v$::jsonb, updated_at = now() WHERE slug = 'watts-wisdom-of-insecurity';
UPDATE public.vault_articles SET lesson_number = 11, display_order = 311, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "What does Frankl mean by reversing the question?", "choices": ["Stop wanting things", "Ask what life is asking of you and answer with action", "Find your purpose by thinking harder"], "correct": 1, "explain": "Meaning is made by responding to the concrete situations in front of you, not found by introspection alone."}, {"q": "What does the meaning-in-life research actually show?", "choices": ["Nothing measurable", "Purpose statements cause better health", "Presence of meaning is associated with better wellbeing and behaviour"], "correct": 2, "explain": "Strong associations in large samples, not proof of cause. The practice earns a promising chip, not a strong one."}]$v$::jsonb, updated_at = now() WHERE slug = 'frankl-meaning-responsibility';
UPDATE public.vault_articles SET lesson_number = 12, display_order = 312, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "Which of these is in the up-to-you column?", "choices": ["What other people think of your rank", "Your rank on the board", "How you judge your rank on the board"], "correct": 2, "explain": "Judgements, aims and effort are yours. The number and other people's reactions are not."}, {"q": "What did the Stoics do about outcomes they could not control?", "choices": ["Aimed at them fully but staked their peace on the aim, not the result", "Pretended they did not want them", "Stopped trying for them"], "correct": 0, "explain": "The reserve clause: full effort, held loosely."}]$v$::jsonb, updated_at = now() WHERE slug = 'epictetus-dichotomy-of-control';
UPDATE public.vault_articles SET lesson_number = 13, display_order = 313, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "Why does Marcus name difficult people before the day begins?", "choices": ["So the difficulty lands on a prepared mind with a gap before the reaction", "To feel superior to them", "To avoid them"], "correct": 0, "explain": "The preparation puts the gap between event and reaction in place in advance."}, {"q": "What is the view from above for?", "choices": ["Detaching from life", "Seeing a problem at its real size so you can act without distortion", "Feeling insignificant"], "correct": 1, "explain": "A change of frame, not a retreat from action."}]$v$::jsonb, updated_at = now() WHERE slug = 'marcus-aurelius-morning-practice';
UPDATE public.vault_articles SET lesson_number = 14, display_order = 314, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "What is Seneca's answer to \"life is too short\"?", "choices": ["It is, so hurry", "It is long enough; most of it is wasted on demands, distraction and postponement", "Time is an illusion"], "correct": 1, "explain": "The essay's whole argument is that the shortage is in the use, not the supply."}, {"q": "What does the weekly audit end with?", "choices": ["A new productivity app", "A feeling of guilt", "One specific hour reclaimed and scheduled"], "correct": 2, "explain": "Awareness changes behaviour when it becomes one concrete move."}]$v$::jsonb, updated_at = now() WHERE slug = 'seneca-on-time';
UPDATE public.vault_articles SET lesson_number = 15, display_order = 315, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "How, according to Aristotle, does a person become brave?", "choices": ["By feeling no fear", "By understanding courage", "By doing brave acts repeatedly until they become the default"], "correct": 2, "explain": "A virtue is a hexis, a settled state formed by repetition, exactly like a skill."}, {"q": "What did the habit-formation study add to the argument?", "choices": ["Automaticity rises with repetition, plateauing after a median of 66 days, and one missed day does not break it", "Willpower is the key", "Habits form in 21 days"], "correct": 0, "explain": "The mechanism is repetition in a stable context, with a wide spread between people."}]$v$::jsonb, updated_at = now() WHERE slug = 'aristotle-habituation';
UPDATE public.vault_articles SET lesson_number = 16, display_order = 316, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "Where do most real changes die?", "choices": ["At the refusal, usually with a sensible-sounding reason", "At the return", "At the ordeal"], "correct": 0, "explain": "The refusal is the quiet exit; naming it is the practice."}, {"q": "How should the monomyth be used here?", "choices": ["As proof that all stories are one", "As a lens that names your stage in a change", "As a screenwriting template"], "correct": 1, "explain": "Its universality is contested; its use as a frame for your own change is what this piece keeps."}]$v$::jsonb, updated_at = now() WHERE slug = 'campbell-heros-journey';
UPDATE public.vault_articles SET lesson_number = 17, display_order = 317, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "Why is the lion not the final stage?", "choices": ["Because lions are weak", "Because refusal cannot create; the child says I will and makes something", "Because the camel was right"], "correct": 1, "explain": "The lion wins the right to refuse; the point is the child's sacred yes."}, {"q": "How much evidence supports the rewrite practice?", "choices": ["It is proven by neuroscience", "Strong trial evidence", "None beyond a plausible mechanism, so the chip says speculative"], "correct": 2, "explain": "Philosophy, not findings. Keep the exercise, drop the certainty."}]$v$::jsonb, updated_at = now() WHERE slug = 'nietzsche-self-overcoming';
UPDATE public.vault_articles SET lesson_number = 18, display_order = 318, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "What defines deliberate practice?", "choices": ["Watching experts", "Many hours of play", "Effortful work at the edge, on the weak part, with feedback"], "correct": 2, "explain": "Ericsson's definition; the hours matter only when they are this kind."}, {"q": "What does the 2014 meta-analysis show about deliberate practice?", "choices": ["It explains a real but partial share of performance differences", "It explains nothing", "It explains everything"], "correct": 0, "explain": "The method is real; the 10,000-hour number is folklore. Promising, not strong."}]$v$::jsonb, updated_at = now() WHERE slug = 'greene-mastery-apprenticeship';
UPDATE public.vault_articles SET lesson_number = 19, display_order = 319, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "What is the cookie jar?", "choices": ["A list of true past proof to reach for at the moment of quitting", "A motivational quote", "A reward for finishing"], "correct": 0, "explain": "Evidence, not affirmation. It works because it is true."}, {"q": "What does the science say about the 40% rule?", "choices": ["It is measured and exact", "The direction is supported by the psychobiological model; the number is a story", "It is completely false"], "correct": 1, "explain": "Perceived effort sets the stopping point and can be moved; no study produced the number."}]$v$::jsonb, updated_at = now() WHERE slug = 'goggins-callused-mind';
UPDATE public.vault_articles SET lesson_number = 20, display_order = 320, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "Where, in this teaching, is mindfulness trained?", "choices": ["Only on the cushion", "Inside ordinary tasks, by doing the thing you are doing", "In retreats"], "correct": 1, "explain": "The dishes are the practice; the cushion is optional."}, {"q": "What does the trial evidence show for mindfulness programmes?", "choices": ["No measurable effect", "Cures for most conditions", "Moderate improvements in anxiety, depression, pain and stress"], "correct": 2, "explain": "Moderate, repeated, real. The everyday form should be expected to do a little less."}]$v$::jsonb, updated_at = now() WHERE slug = 'thich-nhat-hanh-one-thing';
UPDATE public.vault_articles SET lesson_number = 21, display_order = 321, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "What separates the body scan from a relaxation exercise?", "choices": ["It uses music", "It is longer", "You are not trying to make anything happen, only to be in contact with what is there"], "correct": 2, "explain": "Contact, not control. Regions you had stopped feeling come back."}, {"q": "What size of effect does MBSR show in meta-analyses?", "choices": ["Moderate on stress, smaller on anxiety and depression", "None", "Large and curative"], "correct": 0, "explain": "Real, repeatable, moderate. Held better with continued practice."}]$v$::jsonb, updated_at = now() WHERE slug = 'kabat-zinn-full-catastrophe';
UPDATE public.vault_articles SET lesson_number = 22, display_order = 322, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "What is the Centenarian Decathlon?", "choices": ["Ten physical tasks you want at ninety, back-calculated to the capacities to train now", "A supplement stack", "A race for old people"], "correct": 0, "explain": "A reason to train that is specific enough to picture and to plan from."}, {"q": "What kind of evidence links fitness and strength to mortality?", "choices": ["Randomised trials", "Large cohorts with consistent dose-response, as strong as observational medicine gets", "Anecdotes"], "correct": 1, "explain": "Nobody can randomise forty years of training; the inference is well supported and still an inference."}]$v$::jsonb, updated_at = now() WHERE slug = 'attia-centenarian-decathlon';
UPDATE public.vault_articles SET lesson_number = 23, display_order = 323, course_role = 'protocol', read_time_min = 3, quiz = $v$[{"q": "What is the persona, in Jung's sense?", "choices": ["A lie you tell", "The necessary face you build to meet the world, which becomes a problem when mistaken for yourself", "The shadow"], "correct": 1, "explain": "Neutral and needed; the illness is identification with it."}, {"q": "What research supports the direction of the practice?", "choices": ["Brain scans of the persona", "Jung's case studies", "Self-discrepancy and authenticity findings on the gap between the presented and felt self"], "correct": 2, "explain": "Jung's architecture is a model; the gap between ought and actual self has been measured."}]$v$::jsonb, updated_at = now() WHERE slug = 'jung-persona-mask';
UPDATE public.vault_articles SET lesson_number = 25, display_order = 325, course_role = 'recap', read_time_min = 3, quiz = $v$[{"q": "How should the stack be introduced?", "choices": ["Only on rest days", "All nine practices from day one", "In three weeks: morning block and the return first, then the whenever-tools, then training and Sunday"], "correct": 2, "explain": "Running all nine at once is the fastest way to run none. The whenever-tools also need something to happen to."}, {"q": "Which claim did this course NOT make?", "choices": ["Meditation cures disease", "Light and breath move physiology", "A habit is designed"], "correct": 0, "explain": "The healing claim belongs to its author and was labelled speculative. The course kept only what has evidence next to it."}]$v$::jsonb, updated_at = now() WHERE slug = 'wisdom-practice-stack';
